#include <iostream>

int main() {
    int score{72};

    if (score >= 90) {
        std::cout << "A\n";
    } else if (score >= 70) {
        std::cout << "B\n";
    } else {
        std::cout << "C or below\n";
    }

    if (int remainder = score % 10; remainder == 0) {
        std::cout << "round number\n";
    } else {
        std::cout << "remainder " << remainder << '\n';
    }
}

#include <iostream>
#include <vector>

int square(int x);                               // declaration
double average(const std::vector<int>& values);  // declaration

int main() {
    std::cout << square(12) << '\n';
    std::vector<int> marks{80, 92, 71};
    std::cout << average(marks) << '\n';
}

int square(int x) {                              // definition
    return x * x;
}

double average(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    int sum{};
    for (int v : values) sum += v;
    return static_cast<double>(sum) / values.size();
}

#include <iostream>
#include <string>

void swapValues(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

void shout(const std::string& text) {   // read-only, nothing is copied
    std::cout << text << "!\n";
}

int main() {
    int x{1};
    int y{2};
    swapValues(x, y);
    std::cout << "x=" << x << " y=" << y << '\n';

    int& alias = x;   // alias is another name for x
    alias = 10;
    std::cout << "x=" << x << '\n';

    std::string name{"Grace"};
    shout(name);
}

#include <iostream>
#include <string>
#include <utility>

class BankAccount {
public:
    BankAccount(std::string owner, double openingBalance)
        : owner_{std::move(owner)}, balance_{openingBalance} {}

    void deposit(double amount) {
        if (amount > 0) balance_ += amount;
    }

    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance_) return false;
        balance_ -= amount;
        return true;
    }

    double balance() const { return balance_; }
    const std::string& owner() const { return owner_; }

private:
    std::string owner_;
    double balance_;
};

int main() {
    BankAccount account{"Ada", 100.0};
    account.deposit(50);
    bool ok = account.withdraw(500);

    std::cout << account.owner() << ": " << account.balance() << '\n';
    std::cout << std::boolalpha << "withdraw 500 succeeded: " << ok << '\n';
}

